        '能效方向研究压缩机烟气余热回收、调压站余压发电与站场综合能源系统集成，配套用能在线监测与能效对标机制。生态方向面向高寒草甸、水源保护区与自然保护地，研究低扰动施工工艺、表土剥离回覆与植被土壤快速修复评价方法，缩短生态恢复周期。'
